@pytest.mark.to_sparse_semi_structured
@pytest.mark.parametrize("dtype", [torch.float16, torch.bfloat16, torch.float32])
def test_to_sparse_semi_structured_special_values(dtype):
    rows, cols = (32, 64)
    ksparse = 2 if dtype == torch.float32 else 4
    keep = ksparse // 2
    x = torch.zeros((rows, cols), dtype=dtype, device=flag_gems.device)
    specials = torch.tensor(
        [1.9, -1.9, float("inf"), -float("inf"), float("nan")],
        dtype=dtype,
        device=flag_gems.device,
    )
    # Fill every KSPARSE-wide group with exactly `keep` retained slots whose
    # values cycle through the specials, so the pattern stays valid and the
    # NaN / inf / negative bit patterns flow into the retained positions.
    # (+/-0.0 are absent because the mask uses `!= 0`, so a zero value is
    # pruned rather than retained and would break the group count.)
    for g in range(cols // ksparse):
        base = g * ksparse
        for s in range(keep):
            slot = (g + s) % ksparse
            x[:, base + slot] = specials[(g * keep + s) % specials.numel()]
    actual, expected = _assert_sss(x, equal_nan=True)
    assert torch.equal(
        torch.signbit(actual[0]), torch.signbit(expected[0])
    )


